import Application, { Item } from "../models/Application";
export default class NewChatForm extends HTMLFormElement {
    constructor() {
        super(...arguments);
        // Attributes to inject
        this.offerID = null;
        // Models
        this.application = Application.getInstance();
        this.currentUser = this.application.get(Item.CurrentUser);
        this.token = this.application.get(Item.AuthToken);
    }
    async connectedCallback() {
        if (!this.currentUser || !this.token) {
            console.error("User is not authenticated.");
            return;
        }
        this.onsubmit = (event) => this.handleSubmit(event);
    }
    async handleSubmit(event) {
        event.preventDefault();
        if (!this.offerID) {
            console.error("Missing required attributes.");
            return;
        }
        const form = event.target;
        const formData = new FormData(form);
        const message = formData.get("message");
        // const chat: Chat = await ChatFetch.getOrCreateWithMessage(this.offerID, this.currentUser!._id, message, this.token!);
        // if (!chat) {
        //     console.error("Failed to create or retrieve chat.");
        //     return;
        // }
        // window.location.href = `/offer/chat?id=${chat._id}`;
    }
}
